// pytypes.mjs — Python value model helpers.
//
// Value mapping used across the port:
//   Python int   -> BigInt        (exact, arbitrary precision)
//   Python float -> JS number     (IEEE double, same as CPython)
//   Python str   -> JS string
//   Python bool  -> JS boolean
//   Python None  -> null
//   Python list  -> JS Array
//   Python tuple -> PyTuple
//   Python dict  -> PyDict        (insertion-ordered pair list)
//   Python set   -> PySet

export class PyTuple {
  constructor(items = []) {
    this.items = items;
  }
}

export class PySet {
  constructor(items = []) {
    this.items = items;
  }
}

function toIntLike(v) {
  if (typeof v === 'bigint') return v;
  if (typeof v === 'boolean') return v ? 1n : 0n;
  if (typeof v === 'number' && Number.isInteger(v) && Number.isSafeInteger(v)) {
    return BigInt(v);
  }
  return null;
}

// Python `==` semantics for the key types we support (int/float/bool cross-compare).
export function pyKeyEq(a, b) {
  const ia = toIntLike(a);
  const ib = toIntLike(b);
  if (ia !== null && ib !== null) return ia === ib;
  if (typeof a === 'number' && typeof b === 'number') return a === b;
  if (typeof a === 'bigint' && typeof b === 'number') return Number(a) === b;
  if (typeof a === 'number' && typeof b === 'bigint') return a === Number(b);
  if (typeof a === 'string' && typeof b === 'string') return a === b;
  if (a === null || b === null) return a === b;
  if (a instanceof PyTuple && b instanceof PyTuple) {
    return (
      a.items.length === b.items.length &&
      a.items.every((x, i) => pyKeyEq(x, b.items[i]))
    );
  }
  return a === b;
}

export class PyDict {
  constructor(pairs = []) {
    this.pairs = [];
    for (const [k, v] of pairs) this.set(k, v);
  }

  _index(k) {
    for (let i = 0; i < this.pairs.length; i++) {
      if (pyKeyEq(this.pairs[i][0], k)) return i;
    }
    return -1;
  }

  set(k, v) {
    const i = this._index(k);
    if (i >= 0) this.pairs[i][1] = v;
    else this.pairs.push([k, v]);
  }

  get(k) {
    const i = this._index(k);
    return i >= 0 ? this.pairs[i][1] : undefined;
  }

  has(k) {
    return this._index(k) >= 0;
  }

  keys() {
    return this.pairs.map(([k]) => k);
  }

  values() {
    return this.pairs.map(([, v]) => v);
  }

  items() {
    return this.pairs.map(([k, v]) => new PyTuple([k, v]));
  }
}

// --- float repr (CPython repr algorithm: shortest round-trip digits) ---

export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (!Number.isFinite(x)) return x > 0 ? 'inf' : '-inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';

  const neg = x < 0;
  const s = Math.abs(x).toString(); // shortest round-trip digits, like CPython

  // Normalize to: value = 0.digits * 10^decpt (digits: no leading/trailing zeros)
  let mantissa = s;
  let exp = 0;
  const eIdx = s.indexOf('e');
  if (eIdx >= 0) {
    mantissa = s.slice(0, eIdx);
    exp = parseInt(s.slice(eIdx + 1), 10);
  }
  const dotIdx = mantissa.indexOf('.');
  const intPart = dotIdx >= 0 ? mantissa.slice(0, dotIdx) : mantissa;
  const fracPart = dotIdx >= 0 ? mantissa.slice(dotIdx + 1) : '';
  let digits = intPart + fracPart;
  let decpt = intPart.length + exp;
  let lead = 0;
  while (lead < digits.length && digits[lead] === '0') lead++;
  digits = digits.slice(lead).replace(/0+$/, '');
  decpt -= lead;
  if (digits === '') return neg ? '-0.0' : '0.0';

  let out;
  if (decpt > 16 || decpt <= -4) {
    // exponential notation: d[.ddd]e±XX (exponent at least 2 digits)
    const e = decpt - 1;
    const m = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const eAbs = String(Math.abs(e)).padStart(2, '0');
    out = `${m}e${e < 0 ? '-' : '+'}${eAbs}`;
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return neg ? '-' + out : out;
}

// --- string repr (CPython quote selection and escaping) ---

export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

// --- generic repr / str ---

export function pyRepr(v) {
  if (v === null || v === undefined) return 'None';
  if (v === true) return 'True';
  if (v === false) return 'False';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') return pyFloatRepr(v);
  if (typeof v === 'string') return pyStrRepr(v);
  if (Array.isArray(v)) return '[' + v.map(pyRepr).join(', ') + ']';
  if (v instanceof PyTuple) {
    if (v.items.length === 0) return '()';
    if (v.items.length === 1) return '(' + pyRepr(v.items[0]) + ',)';
    return '(' + v.items.map(pyRepr).join(', ') + ')';
  }
  if (v instanceof PyDict) {
    return (
      '{' +
      v.pairs.map(([k, val]) => pyRepr(k) + ': ' + pyRepr(val)).join(', ') +
      '}'
    );
  }
  if (v instanceof PySet) {
    if (v.items.length === 0) return 'set()';
    return '{' + v.items.map(pyRepr).join(', ') + '}';
  }
  return String(v);
}

// Python str(): identical to repr except top-level strings stay unquoted.
export function pyStr(v) {
  if (typeof v === 'string') return v;
  return pyRepr(v);
}

export function pyTypeName(v) {
  if (v === null || v === undefined) return 'NoneType';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'number') return 'float';
  if (typeof v === 'string') return 'str';
  if (Array.isArray(v)) return 'list';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PySet) return 'set';
  return 'object';
}

// isinstance(x, int) — bool is a subclass of int in Python.
export function isPyInt(v) {
  return typeof v === 'bigint' || typeof v === 'boolean';
}

export function isPyIntOrFloat(v) {
  return isPyInt(v) || typeof v === 'number';
}

// Python-style modulo (result takes the sign of the divisor).
export function pyMod(a, b) {
  if (typeof a === 'bigint' || typeof b === 'bigint') {
    const x = typeof a === 'boolean' ? (a ? 1n : 0n) : BigInt(a);
    const y = typeof b === 'boolean' ? (b ? 1n : 0n) : BigInt(b);
    return ((x % y) + y) % y;
  }
  return ((a % b) + b) % b;
}

