// pyliteral.mjs — parser for Python literal syntax (the subset `eval` accepts
// for plain data): dicts, lists, tuples, sets, strings (with escapes, raw and
// triple-quoted forms, adjacent-literal concatenation), ints (dec/hex/oct/bin,
// underscores), floats, True/False/None, unary +/- on numbers.

import { PyDict, PyTuple, PySet } from './pytypes.mjs';

export function pyEval(src) {
  let pos = 0;

  const skipWs = () => {
    while (pos < src.length && /\s/.test(src[pos])) pos++;
  };

  const expect = (ch) => {
    skipWs();
    if (src[pos] !== ch) {
      throw new SyntaxError(`expected '${ch}' at position ${pos}`);
    }
  };

  function parseEscape() {
    const e = src[pos++];
    switch (e) {
      case 'n': return '\n';
      case 't': return '\t';
      case 'r': return '\r';
      case 'a': return '\x07';
      case 'b': return '\b';
      case 'f': return '\f';
      case 'v': return '\v';
      case '\\': return '\\';
      case "'": return "'";
      case '"': return '"';
      case '\n': return ''; // line continuation
      case 'x': {
        const h = src.slice(pos, pos + 2);
        pos += 2;
        return String.fromCodePoint(parseInt(h, 16));
      }
      case 'u': {
        const h = src.slice(pos, pos + 4);
        pos += 4;
        return String.fromCodePoint(parseInt(h, 16));
      }
      case 'U': {
        const h = src.slice(pos, pos + 8);
        pos += 8;
        return String.fromCodePoint(parseInt(h, 16));
      }
      default:
        if (e >= '0' && e <= '7') {
          let oct = e;
          while (oct.length < 3 && src[pos] >= '0' && src[pos] <= '7') {
            oct += src[pos++];
          }
          return String.fromCodePoint(parseInt(oct, 8));
        }
        // unknown escape: Python keeps the backslash
        return '\\' + e;
    }
  }

  function parseString(raw = false) {
    let result = '';
    for (;;) {
      skipWs();
      const q = src[pos];
      const triple = src.startsWith(q.repeat(3), pos);
      pos += triple ? 3 : 1;
      while (pos < src.length) {
        if (triple ? src.startsWith(q.repeat(3), pos) : src[pos] === q) {
          pos += triple ? 3 : 1;
          break;
        }
        const ch = src[pos++];
        result += !raw && ch === '\\' ? parseEscape() : ch;
      }
      // adjacent string literal concatenation: "a" "b" -> "ab"
      skipWs();
      const nxt = src[pos];
      if (nxt !== "'" && nxt !== '"') break;
    }
    return result;
  }

  function parseNumber() {
    if (src.startsWith('0x', pos) || src.startsWith('0X', pos)) {
      pos += 2;
      let h = '';
      while (/[0-9a-fA-F_]/.test(src[pos] || '')) h += src[pos++];
      return BigInt('0x' + h.replace(/_/g, ''));
    }
    if (src.startsWith('0o', pos) || src.startsWith('0O', pos)) {
      pos += 2;
      let o = '';
      while (/[0-7_]/.test(src[pos] || '')) o += src[pos++];
      return BigInt('0o' + o.replace(/_/g, ''));
    }
    if (src.startsWith('0b', pos) || src.startsWith('0B', pos)) {
      pos += 2;
      let b = '';
      while (/[01_]/.test(src[pos] || '')) b += src[pos++];
      return BigInt('0b' + b.replace(/_/g, ''));
    }
    let s = '';
    let isFloat = false;
    while (/[0-9_]/.test(src[pos] || '')) s += src[pos++];
    if (src[pos] === '.') {
      isFloat = true;
      s += src[pos++];
      while (/[0-9_]/.test(src[pos] || '')) s += src[pos++];
    }
    if (src[pos] === 'e' || src[pos] === 'E') {
      isFloat = true;
      s += src[pos++];
      if (src[pos] === '+' || src[pos] === '-') s += src[pos++];
      while (/[0-9_]/.test(src[pos] || '')) s += src[pos++];
    }
    s = s.replace(/_/g, '');
    return isFloat ? Number(s) : BigInt(s);
  }

  function parseBrace() {
    pos++; // consume '{'
    skipWs();
    if (src[pos] === '}') {
      pos++;
      return new PyDict();
    }
    const first = parseValue();
    skipWs();
    if (src[pos] === ':') {
      const d = new PyDict();
      pos++;
      d.set(first, parseValue());
      skipWs();
      while (src[pos] === ',') {
        pos++;
        skipWs();
        if (src[pos] === '}') break;
        const k = parseValue();
        expect(':');
        pos++;
        d.set(k, parseValue());
        skipWs();
      }
      expect('}');
      pos++;
      return d;
    }
    // set literal
    const items = [first];
    while (src[pos] === ',') {
      pos++;
      skipWs();
      if (src[pos] === '}') break;
      items.push(parseValue());
      skipWs();
    }
    expect('}');
    pos++;
    return new PySet(items);
  }

  function parseList() {
    pos++; // consume '['
    const items = [];
    skipWs();
    if (src[pos] === ']') {
      pos++;
      return items;
    }
    for (;;) {
      items.push(parseValue());
      skipWs();
      if (src[pos] !== ',') break;
      pos++;
      skipWs();
      if (src[pos] === ']') break;
    }
    expect(']');
    pos++;
    return items;
  }

  function parseParen() {
    pos++; // consume '('
    skipWs();
    if (src[pos] === ')') {
      pos++;
      return new PyTuple([]);
    }
    const first = parseValue();
    skipWs();
    if (src[pos] !== ',') {
      expect(')');
      pos++;
      return first; // plain parenthesized expression
    }
    const items = [first];
    while (src[pos] === ',') {
      pos++;
      skipWs();
      if (src[pos] === ')') break;
      items.push(parseValue());
      skipWs();
    }
    expect(')');
    pos++;
    return new PyTuple(items);
  }

  function parseValue() {
    skipWs();
    const ch = src[pos];
    if (ch === '{') return parseBrace();
    if (ch === '[') return parseList();
    if (ch === '(') return parseParen();
    if (ch === "'" || ch === '"') return parseString(false);
    if ((ch === 'r' || ch === 'R') && (src[pos + 1] === "'" || src[pos + 1] === '"')) {
      pos++;
      return parseString(true);
    }
    if (ch === '+' || ch === '-') {
      if (/[0-9.]/.test(src[pos + 1] || '')) {
        pos++;
        const n = parseNumber();
        return ch === '-' ? -n : n;
      }
      throw new SyntaxError(`unexpected '${ch}' at position ${pos - 1}`);
    }
    if (/[0-9.]/.test(ch)) return parseNumber();
    if (src.startsWith('True', pos)) { pos += 4; return true; }
    if (src.startsWith('False', pos)) { pos += 5; return false; }
    if (src.startsWith('None', pos)) { pos += 4; return null; }
    throw new SyntaxError(`unexpected character '${ch}' at position ${pos}`);
  }

  const value = parseValue();
  skipWs();
  if (pos < src.length) {
    throw new SyntaxError(`unexpected trailing characters at position ${pos}`);
  }
  return value;
}

