    skipWs();
    if (src[pos] !== ',') {
      expect(')');
      pos++;
      return first; // plain parenthesized expression
    }
    const items = [first];
    while (src[pos] === ',') {
      pos++;
      skipWs();
      if (src[pos] === ')') break;
      items.push(parseValue());
      skipWs();
    }
    expect(')');
    pos++;
    return new PyTuple(items);
  }

  function parseValue() {
    skipWs();
    const ch = src[pos];
    if (ch === '{') return parseBrace();
    if (ch === '[') return parseList();
