// dictutils.mjs — reimplementation of the boltons.dictutils classes used by
// the source program: OMD (OrderedMultiDict) and FrozenDict.

import { PyDict, PyTuple, pyKeyEq, pyRepr } from './pytypes.mjs';

export class OMD {
  constructor() {
    this.pairs = []; // all (key, value) pairs, multi-values preserved
  }

  add(k, v) {
    this.pairs.push([k, v]);
  }

  // Unique keys in first-insertion order (like list(omd.keys())).
  keys() {
    const out = [];
    for (const [k] of this.pairs) {
      if (!out.some((seen) => pyKeyEq(seen, k))) out.push(k);
    }
    return out;
  }

  // omd[k] returns the most recently added value for k.
  getLast(k) {
    for (let i = this.pairs.length - 1; i >= 0; i--) {
      if (pyKeyEq(this.pairs[i][0], k)) return this.pairs[i][1];
    }
    return undefined;
  }

  // dict(omd): unique keys, last value wins.
  toDict() {
    const d = new PyDict();
    for (const k of this.keys()) d.set(k, this.getLast(k));
    return d;
  }

  repr() {
    const tuples = this.pairs.map(([k, v]) => new PyTuple([k, v]));
    return 'OrderedMultiDict(' + pyRepr(tuples) + ')';
  }
}

export class FrozenDict {
  constructor(dictLike) {
    this.dict = dictLike; // a PyDict
  }

  items() {
    return this.dict.items();
  }

  repr() {
    return 'FrozenDict(' + pyRepr(this.dict) + ')';
  }
}

