// argparse.mjs — minimal emulation of the Python argparse configuration used
// by the source program:
//
//   parser.add_argument('--a', type=str, required=True,
//                       help='Nested dictionary structure')
//
// Mirrors argparse behavior: usage/error text on stderr with exit code 2,
// -h/--help on stdout with exit code 0, supports "--a VALUE" and "--a=VALUE".

import { basename } from 'node:path';

export function parseArgs(argv) {
  const prog = basename(argv[1] || 'test19.mjs');
  const usage = `usage: ${prog} [-h] --a A`;

  const fail = (msg) => {
    process.stderr.write(`${usage}\n${prog}: error: ${msg}\n`);
    process.exit(2);
  };

  const printHelp = () => {
    process.stdout.write(
      `${usage}\n\n` +
        `options:\n` +
        `  -h, --help  show this help message and exit\n` +
        `  --a A       Nested dictionary structure\n`
    );
    process.exit(0);
  };

  const rest = argv.slice(2);
  let aValue;
  let aSeen = false;
  const extras = [];

  for (let i = 0; i < rest.length; i++) {
    const arg = rest[i];
    if (arg === '-h' || arg === '--help') {
      printHelp();
    } else if (arg === '--a') {
      if (i + 1 >= rest.length) fail('argument --a: expected one argument');
      aValue = rest[++i];
      aSeen = true;
    } else if (arg.startsWith('--a=')) {
      aValue = arg.slice(4);
      aSeen = true;
    } else {
      extras.push(arg);
    }
  }

  if (!aSeen) fail('the following arguments are required: --a');
  if (extras.length > 0) fail(`unrecognized arguments: ${extras.join(' ')}`);

  return { a: aValue };
}

